"use strict";(self.webpackChunkajudafacitysistemas=self.webpackChunkajudafacitysistemas||[]).push([[5803],{2495:(e,a,o)=>{o.r(a),o.d(a,{assets:()=>c,contentTitle:()=>r,default:()=>l,frontMatter:()=>t,metadata:()=>i,toc:()=>p});var s=o(4848),n=o(8453);const t={title:"Como verificar sua empresa na Meta e vincular o WhatsApp Business",description:"Neste artigo, vou mostrar como verificar sua empresa na Meta e como conferir se o WhatsApp Business est\xe1 vinculado ao mesmo portf\xf3lio empresarial. Importante..."},r=void 0,i={id:"configuracoes/como-verificar-sua-empresa-na-meta-e-vincular-o-whatsapp-business",title:"Como verificar sua empresa na Meta e vincular o WhatsApp Business",description:"Neste artigo, vou mostrar como verificar sua empresa na Meta e como conferir se o WhatsApp Business est\xe1 vinculado ao mesmo portf\xf3lio empresarial. Importante...",source:"@site/docs/configuracoes/como-verificar-sua-empresa-na-meta-e-vincular-o-whatsapp-business.mdx",sourceDirName:"configuracoes",slug:"/configuracoes/como-verificar-sua-empresa-na-meta-e-vincular-o-whatsapp-business",permalink:"/docs/configuracoes/como-verificar-sua-empresa-na-meta-e-vincular-o-whatsapp-business",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{title:"Como verificar sua empresa na Meta e vincular o WhatsApp Business",description:"Neste artigo, vou mostrar como verificar sua empresa na Meta e como conferir se o WhatsApp Business est\xe1 vinculado ao mesmo portf\xf3lio empresarial. Importante..."},sidebar:"tutorialSidebar",previous:{title:"Como resolver problemas no WhatsApp de sincronismo entre mensagem do celular e navegador?",permalink:"/docs/configuracoes/como-resolver-problemas-no-whatsapp-de-sincronismo-entre-mensagem-do-celular-e-navegador-"},next:{title:"Mapa de URLS para Facebook Pixel",permalink:"/docs/configuracoes/mapa-de-urls-para-facebook-pixel"}},c={},p=[];function m(e){return(0,s.jsx)(s.Fragment,{children:(0,s.jsx)(s.Fragment,{children:(0,s.jsx)("div",{dangerouslySetInnerHTML:{__html:'\n  \n<p>Neste artigo, vou mostrar como verificar sua empresa na Meta e como conferir se o WhatsApp Business est\xe1 vinculado ao mesmo portf\xf3lio empresarial.</p>\n\n<p><strong>Importante:</strong> a verifica\xe7\xe3o da empresa n\xe3o garante, sozinha, que o WhatsApp nunca ser\xe1 suspenso. Tamb\xe9m \xe9 necess\xe1rio seguir as pol\xedticas do WhatsApp e falar somente com pessoas que autorizaram o contato.</p>\n\n<p><strong>Antes de come\xe7ar:</strong> deixe separado o CNPJ ou CCMEI, a raz\xe3o social exatamente como aparece no documento e um documento oficial leg\xedvel, completo e sem cortes.</p>\n\n<p><strong>Passo 1. Entre na conta correta:</strong> acesse o <a href="https://business.facebook.com/" target="_blank" rel="noopener"><strong>Meta Business Suite</strong></a> e entre com a conta que administra a empresa. Se aparecer mais de um portf\xf3lio empresarial, escolha o que pertence ao cliente.</p>\n\n<p><strong>Passo 2. Abra a Central de Seguran\xe7a:</strong> no menu de configura\xe7\xf5es, entre em <strong>Central de Seguran\xe7a</strong>. Depois, localize o bloco <strong>Verifica\xe7\xe3o da empresa</strong> e clique em <strong>Iniciar verifica\xe7\xe3o</strong>.</p>\n<figure><img style="max-width: 100%; height: auto;" decoding="async" src="https://manual.facity.com.br/wp-content/uploads/2026/09/01-central-seguranca.jpg" alt="Central de Seguran\xe7a da Meta com o bloco de verifica\xe7\xe3o da empresa e o bot\xe3o Iniciar verifica\xe7\xe3o destacados" loading="lazy"></figure>\n\n<p><strong>Passo 3. Confira as informa\xe7\xf5es da empresa:</strong> antes de iniciar, verifique se o portf\xf3lio est\xe1 correto e se os dados s\xe3o do cliente. O status <strong>N\xe3o verificada</strong> significa que a an\xe1lise ainda n\xe3o foi conclu\xedda.</p>\n<figure><img style="max-width: 100%; height: auto;" decoding="async" src="https://manual.facity.com.br/wp-content/uploads/2026/09/02-informacoes-empresa.jpg" alt="P\xe1gina Informa\xe7\xf5es da empresa mostrando o status de verifica\xe7\xe3o" loading="lazy"></figure>\n\n<p><strong>Passo 4. Leia as instru\xe7\xf5es:</strong> a Meta mostrar\xe1 as etapas da verifica\xe7\xe3o. Leia as informa\xe7\xf5es e clique em <strong>Come\xe7ar</strong>.</p>\n<figure><img style="max-width: 100%; height: auto;" decoding="async" src="https://manual.facity.com.br/wp-content/uploads/2026/09/04-inicio-verificacao.jpg" alt="Janela inicial da verifica\xe7\xe3o da empresa na Meta com as tr\xeas a\xe7\xf5es necess\xe1rias" loading="lazy"></figure>\n\n<p><strong>Passo 5. Selecione o pa\xeds:</strong> escolha <strong>Brasil</strong> no campo de pa\xeds e clique em <strong>Avan\xe7ar</strong>.</p>\n<figure><img style="max-width: 100%; height: auto;" decoding="async" src="https://manual.facity.com.br/wp-content/uploads/2026/09/05-pais-brasil.png" alt="Tela de sele\xe7\xe3o do pa\xeds com Brasil escolhido" loading="lazy"></figure>\n\n<p><strong>Passo 6. Escolha o tipo da empresa:</strong> selecione a op\xe7\xe3o que corresponde \xe0 constitui\xe7\xe3o real da empresa. N\xe3o escolha pelo nome fantasia. Se tiver d\xfavida, confira o CNPJ, o CCMEI ou o contrato social.</p>\n<figure><img style="max-width: 100%; height: auto;" decoding="async" src="https://manual.facity.com.br/wp-content/uploads/2026/09/06-tipo-empresa.jpg" alt="Tela da Meta com as op\xe7\xf5es de tipo de empresa" loading="lazy"></figure>\n\n<p><strong>Passo 7. Confirme o registro oficial:</strong> se essa pergunta aparecer, empresas com <strong>CNPJ</strong> ou <strong>CCMEI</strong> normalmente devem escolher <strong>Tem registro</strong>. Depois, clique em <strong>Avan\xe7ar</strong>.</p>\n<figure><img style="max-width: 100%; height: auto;" decoding="async" src="https://manual.facity.com.br/wp-content/uploads/2026/09/07-registro-oficial.jpg" alt="Tela da Meta perguntando se a empresa tem registro oficial, com Tem registro selecionado" loading="lazy"></figure>\n\n<p><strong>Passo 8. Preencha os dados oficiais:</strong> informe o CNPJ ou n\xfamero de registro e o nome jur\xeddico exatamente como aparecem nos documentos. N\xe3o troque a raz\xe3o social pelo nome fantasia.</p>\n<figure><img style="max-width: 100%; height: auto;" decoding="async" src="https://manual.facity.com.br/wp-content/uploads/2026/09/08-dados-oficiais.jpg" alt="Formul\xe1rio da Meta para informar identifica\xe7\xe3o fiscal e nome oficial da empresa" loading="lazy"></figure>\n\n<p><strong>Passo 9. Envie o documento, se for solicitado:</strong> se a Meta n\xe3o encontrar o registro automaticamente, ela poder\xe1 pedir um documento. Envie um arquivo oficial, n\xedtido, completo e sem cortes.</p>\n<figure><img style="max-width: 100%; height: auto;" decoding="async" src="https://manual.facity.com.br/wp-content/uploads/2026/09/09-documentos-aceitos.jpg" alt="Lista de documentos aceitos pela Meta para confirmar o nome da empresa" loading="lazy"></figure>\n\n<p><strong>Passo 10. Confira o WhatsApp Business:</strong> a verifica\xe7\xe3o da empresa e o v\xednculo do WhatsApp s\xe3o etapas relacionadas, mas n\xe3o s\xe3o a mesma coisa. No Meta Business Suite, abra <strong>Configura\xe7\xf5es</strong> &gt; <strong>Contas</strong> &gt; <strong>Contas do WhatsApp</strong>.</p>\n<ol>\n<li>Selecione a conta do WhatsApp Business do cliente.</li>\n<li>Confira o status da empresa e o status da conta.</li>\n<li>Abra <strong>Phone numbers</strong> ou <strong>N\xfameros de telefone</strong>.</li>\n<li>Confirme se o n\xfamero correto est\xe1 vinculado.</li>\n</ol>\n<figure><img style="max-width: 100%; height: auto;" decoding="async" src="https://manual.facity.com.br/wp-content/uploads/2026/09/03-conta-whatsapp.jpg" alt="P\xe1gina Contas do WhatsApp mostrando a conta selecionada e o status da verifica\xe7\xe3o" loading="lazy"></figure>\n\n<p>Se a conta ou o n\xfamero n\xe3o aparecer, n\xe3o crie uma segunda conta antes de conferir se o WhatsApp j\xe1 est\xe1 vinculado a outro portf\xf3lio empresarial.</p>\n\n<p><strong>Depois de enviar:</strong> aguarde a an\xe1lise da Meta. N\xe3o envie documentos de outra empresa, n\xe3o tente v\xe1rias vezes com nomes diferentes e mantenha os dados do neg\xf3cio atualizados.</p>\n\n<p>E pronto! Primeiro voc\xea verifica a empresa; depois, confirma se a conta e o n\xfamero do WhatsApp Business est\xe3o no portf\xf3lio correto.</p>\n\n<p>Como a Meta pode alterar nomes de menus e documentos aceitos, siga sempre o que aparecer na sua pr\xf3pria conta. Consulte tamb\xe9m a <a href="https://business.whatsapp.com/policy/preview?lang=pt_BR" target="_blank" rel="noopener"><strong>Pol\xedtica de Mensagens do WhatsApp Business</strong></a>.</p>\n\n'}})})})}function l(e={}){const{wrapper:a}={...(0,n.R)(),...e.components};return a?(0,s.jsx)(a,{...e,children:(0,s.jsx)(m,{...e})}):m()}},8453:(e,a,o)=>{o.d(a,{R:()=>r,x:()=>i});var s=o(6540);const n={},t=s.createContext(n);function r(e){const a=s.useContext(t);return s.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function i(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:r(e.components),s.createElement(t.Provider,{value:a},e.children)}}}]);